                {
                    myGame.Status = "Won";
                    myGame.ActiveTeam = team.Id.ToString();
                    _context.SaveChanges();
                    player.Status = "Won";
                }
                else
                {
                    if(player.Status =="Choose Action")
                    { 
                    foreach (Actions action in actions)
                    {
                        GameHelpers.AddActionExt(actionWithStates, action, _context, myGame, myTeam, myStates);
                    }
                    }
                }
                player.actionWithStates = actionWithStates;
